// Compendium.ptu.effects.Item.DJF77iklb3nnGp2v
const itemUuid = context.message?.flags?.ptu?.reminder?.item;
const item = await fromUuid(itemUuid);
const actor = item?.actor;

if (!item || !actor) {
  ui.notifications.error("Could not find source effect or actor");
  return;
}

const newEffect = await fromUuid("Compendium.ptu.effects.Item.DJF77iklb3nnGp2v");

if (!newEffect) {
  ui.notifications.error("Could not find new effect to apply");
  return;
}

await actor.createEmbeddedDocuments("Item", [{...newEffect}]);
await item.delete();

console.log("Applied!", { arguments })
